from __future__ import annotations
import argparse,json
from pathlib import Path
HTML='''<!doctype html><meta charset="utf-8"><title>Bitcoin Temporal Stability Field</title><style>body{font-family:system-ui;margin:0;background:#0b0d10;color:#e8edf2}main{max-width:1500px;margin:auto;padding:24px}canvas{width:100%;border:1px solid #29313a;background:#10151b}p{color:#9eabb7}.controls{display:flex;gap:16px;margin:12px 0}</style><main><h1>Bitcoin Temporal Stability Field</h1><p>Log price + F(t, tau)</p><div class="controls"><label>Metric <select id="metric"><option>stability</option><option>regime</option><option>trend</option><option>volatility</option><option>drawdown_pressure</option></select></label><span id="hover"></span></div><canvas id="price" width="1450" height="360"></canvas><canvas id="field" width="1450" height="300"></canvas></main><script>const DATA=__DATA__,pc=document.querySelector("#price"),fc=document.querySelector("#field"),p=pc.getContext("2d"),f=fc.getContext("2d"),metric=document.querySelector("#metric"),hover=document.querySelector("#hover"),T=DATA.timeline,C=DATA.cells,scales=DATA.scales.slice().reverse();function draw(){p.clearRect(0,0,pc.width,pc.height);f.clearRect(0,0,fc.width,fc.height);if(!T.length)return;const logs=T.map(x=>Math.log(x.price_usd)),lo=Math.min(...logs),hi=Math.max(...logs);p.beginPath();T.forEach((x,i)=>{const X=i/(T.length-1)*(pc.width-40)+20,Y=pc.height-20-(logs[i]-lo)/(hi-lo)*(pc.height-40);i?p.lineTo(X,Y):p.moveTo(X,Y)});p.strokeStyle="#dce6ef";p.stroke();const byTime=new Map(T.map((x,i)=>[x.time,i])),h=fc.height/scales.length,w=(fc.width-80)/T.length,m=metric.value;C.forEach(x=>{const i=byTime.get(x.time),y=scales.indexOf(x.scale);if(i===undefined||y<0)return;let v=x[m];if(m==="regime"||m==="trend")v=(v+1)/2;v=Math.max(0,Math.min(1,v));f.fillStyle="hsl("+(v*120)+" 70% 45%)";f.fillRect(80+i*w,y*h,Math.max(1,w+.3),h)});f.fillStyle="#dce6ef";f.font="14px system-ui";scales.forEach((s,i)=>f.fillText(s,20,i*h+h/2+5))}metric.onchange=draw;draw();fc.onmousemove=e=>{const r=fc.getBoundingClientRect(),i=Math.floor((e.clientX-r.left)/r.width*T.length);if(T[i])hover.textContent=T[i].time.slice(0,10)+" | $"+T[i].price_usd.toFixed(2)+" | coherence "+T[i].coherence+" | pressure "+T[i].transition_pressure}</script>'''
def main():
    p=argparse.ArgumentParser();p.add_argument("--input",type=Path,default=Path("data/bitcoin/bitcoin_temporal_field.json"));p.add_argument("--out",type=Path,default=Path("data/bitcoin/bitcoin_temporal_field.html"));a=p.parse_args();data=json.loads(a.input.read_text(encoding="utf-8"));a.out.write_text(HTML.replace("__DATA__",json.dumps(data)),encoding="utf-8");print(f"Wrote {a.out}")
if __name__=="__main__":main()
